-- Zacarini 2.3.7: Metas de Vendas!A25:O54 (metas REAL VENDIDO).
-- 132 valores mensais: quatro linhas e sete lojas (Cassilândia apenas como meta futura).
-- Não alterar metas homologadas; só seis filiais têm dados operacionais.
ON CONFLICT (codigo,competencia) DO UPDATE SET
 grupo=excluded.grupo, dimensao=excluded.dimensao, rotulo=excluded.rotulo, texto=excluded.texto,
 valor=excluded.valor, unidade=excluded.unidade, origem_aba=excluded.origem_aba,
 origem_celula=excluded.origem_celula, versao=excluded.versao
 WHERE public.compras_dashboard_config_237.situacao='referencia';
